{"command":"$ErrorActionPreference = 'Stop'
$repo = 'edburns/dd-3069621-win32-x64-01'
$pr = 14
$expectedHead = '18ff495573c5698e77a6d570f31142933daa66c5'
$expectedReview = [long]5331212455
$expectedBase = 'experiment/shepherd-control'
if ($expectedBase -eq 'main') { throw "ERROR: BASE_BRANCH must never be 'main'." }
$prRaw = gh pr view $pr -R $repo --json state,isDraft,headRefOid,headRefName,baseRefName,mergeable,mergeStateStatus
if ($LASTEXITCODE -ne 0) { throw 'SHEPHERD FAILED: unable to inspect PR final state.' }
$info = $prRaw | ConvertFrom-Json
if ($info.state -ne 'OPEN' -or $info.isDraft) { throw 'SHEPHERD FAILED: PR is not open and ready.' }
if ($info.headRefOid -ne $expectedHead) { throw "SHEPHERD FAILED: PR HEAD changed from reviewed $expectedHead to $($info.headRefOid)." }
if ($info.baseRefName -ne $expectedBase) {
  gh pr edit $pr -R $repo --base $expectedBase
  if ($LASTEXITCODE -ne 0) { throw "SHEPHERD FAILED: could not set PR base to '$expectedBase'." }
  $baseRaw = gh pr view $pr -R $repo --json baseRefName
  if ($LASTEXITCODE -ne 0) { throw 'SHEPHERD FAILED: unable to verify corrected PR base.' }
  $actualBase = ($baseRaw | ConvertFrom-Json).baseRefName
  if ($actualBase -ne $expectedBase) { throw "SHEPHERD FAILED: PR base remains '$actualBase'." }
}
$reviewsRaw = gh api "/repos/$repo/pulls/$pr/reviews"
if ($LASTEXITCODE -ne 0) { throw 'SHEPHERD FAILED: unable to inspect Copilot reviews.' }
$review = @(($reviewsRaw | ConvertFrom-Json) | Where-Object { [long]$_.id -eq $expectedReview -and $_.commit_id -eq $expectedHead -and $_.user.login -match '(?i)^copilot-pull-request-reviewer(\[bot\])?$' })
if ($review.Count -ne 1) { throw 'SHEPHERD FAILED: current-head Copilot review could not be verified.' }
$body = [string]$review[0].body
if ($body -match "(?i)wasn.t able to review" -and $body -match '(?i)maximum number of files') { throw 'SHEPHERD FAILED: Copilot review refused because the PR exceeds the maximum number of files.' }
$query = @'
query($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      reviewThreads(first: 100) {
        nodes { id isResolved comments(first: 1) { nodes { databaseId } } }
        pageInfo { hasNextPage }
      }
    }
  }
}
'@
$threadsRaw = gh api graphql -F owner='edburns' -F name='dd-3069621-win32-x64-01' -F number=$pr -f query=$query
if ($LASTEXITCODE -ne 0) { throw 'SHEPHERD FAILED: unable to inspect review threads.' }
$threadData = $threadsRaw | ConvertFrom-Json
$threads = $threadData.data.repository.pullRequest.reviewThreads
if ($threads.pageInfo.hasNextPage) { throw 'SHEPHERD FAILED: review thread count exceeds final-gate query capacity.' }
$unresolved = @($threads.nodes | Where-Object { -not $_.isResolved })
if ($unresolved.Count -gt 0) { throw "SHEPHERD FAILED: $($unresolved.Count) unresolved review thread(s) remain." }
$checksRaw = gh pr checks $pr -R $repo --json name,state,bucket,workflow
$checksExit = $LASTEXITCODE
if ($checksExit -ne 0 -and -not $checksRaw) { throw 'SHEPHERD FAILED: unable to inspect required checks.' }
$checks = @($checksRaw | ConvertFrom-Json)
$bad = @($checks | Where-Object { $_.bucket -ne 'pass' -and $_.name -notmatch '(?i)Block remove-before-merge paths|No remove-before-merge directories' })
if ($bad.Count -gt 0) { throw "SHEPHERD FAILED: $($bad.Count) non-exempt check(s) are not passing." }
for ($attempt = 1; $attempt -le 6 -and $info.mergeable -eq 'UNKNOWN'; $attempt++) {
  Start-Sleep -Seconds 10
  $prRaw = gh pr view $pr -R $repo --json state,isDraft,headRefOid,headRefName,baseRefName,mergeable,mergeStateStatus
  if ($LASTEXITCODE -ne 0) { throw 'SHEPHERD FAILED: unable to refresh mergeability.' }
  $info = $prRaw | ConvertFrom-Json
}
if ($info.mergeable -eq 'CONFLICTING') { throw "SHEPHERD FAILED: PR #$pr conflicts with '$expectedBase'; local conflict resolution is required." }
if ($info.mergeable -ne 'MERGEABLE') { throw "SHEPHERD FAILED: mergeability remained '$($info.mergeable)'." }
Write-Output "FINAL_HEAD=$($info.headRefOid)"
Write-Output "FINAL_BASE=$($info.baseRefName)"
Write-Output "MERGEABLE=$($info.mergeable)"
Write-Output "MERGE_STATE=$($info.mergeStateStatus)"
Write-Output "UNRESOLVED_THREADS=$($unresolved.Count)"
Write-Output "CHECK_COUNT=$($checks.Count)"","description":"Verify final merge gates","initial_wait":600,"mode":"sync"}
